import{_ as t,C as c,o as a,c as l,ak as o,E as i}from"./chunks/framework.DxrHb2fb.js";const u=JSON.parse('{"title":"图标","description":"","frontmatter":{},"headers":[],"relativePath":"design/icons.md","filePath":"design/icons.md","lastUpdated":1790029076000}'),r={name:"design/icons.md"};function h(s,e,n,p,x,g){const d=c("XhTokenTable");return a(),l("div",null,[e[0]||(e[0]=o('<h1 id="图标" tabindex="-1">图标 <a class="header-anchor" href="#图标" aria-label="Permalink to &quot;图标&quot;">​</a></h1><p>图标是界面里最小的一种&quot;字&quot;：跟着文字的字号、颜色与基线走，不自己发光。库里有两条图标通道——使用者放进部件的图标（<code>@xihan-ui/icons</code> 或任何 SVG 集）与皮肤自绘的兜底字形（<code>--xh-glyph-mark-*</code>），两条通道取同一把尺、同一支颜色。</p><h2 id="首方图标集" tabindex="-1">首方图标集 <a class="header-anchor" href="#首方图标集" aria-label="Permalink to &quot;首方图标集&quot;">​</a></h2><p><code>@xihan-ui/icons</code> 是一套结构化数据：每枚图标是名字、<code>viewBox</code> 与若干节点，渲染端逐节点创建元素，运行期不解析字符串。首方集覆盖中后台的常用语义，逐枚手绘、统一 24 网格与 2 粗描边，按方向与布局、文件与文档、文本编辑、媒体与设备、通信、状态与安全、数据与图表、系统与账户、商业场景分组。它不打算穷尽：换 Lucide、Tabler 或自绘集，把 SVG 目录交给转换器即可，打包器按引用逐枚摇树。用法与转换见 <a href="/guide/icons">图标集</a>。</p><h2 id="尺寸随控件档" tabindex="-1">尺寸随控件档 <a class="header-anchor" href="#尺寸随控件档" aria-label="Permalink to &quot;尺寸随控件档&quot;">​</a></h2>',5)),i(d,{names:["--xh-glyph-size-text","--xh-glyph-size-sm","--xh-glyph-size-md","--xh-glyph-size-lg","--xh-glyph-size-xl","--xh-glyph-size-2xl","--xh-glyph-size-3xl","--xh-glyph-size-4xl"],notes:{"--xh-glyph-size-text":"随文 1em：只给 Tag、Kbd、Breadcrumb、Typography、Highlight 这类纯行内文字组件","--xh-glyph-size-sm":"sm 档控件内图标","--xh-glyph-size-md":"md 档控件内图标（缺省）","--xh-glyph-size-lg":"lg 档控件内图标","--xh-glyph-size-xl":"面板与卡片的题图","--xh-glyph-size-2xl":"空状态、结果页的插图位","--xh-glyph-size-3xl":"大插图","--xh-glyph-size-4xl":"特大插图"}}),e[1]||(e[1]=o('<ul><li>控件内图标随 <code>size</code> 档取 16 / 20 / 24px：Action Control、Field Chrome、Collection Item 三份配方按档下发 <code>--xh-icon-size</code>，皮肤缺省值只能是 <code>var(--xh-&lt;组件&gt;-icon-size, var(--xh-glyph-size-md))</code> 并随 <code>data-size</code> 换档。</li><li>描边三档 <code>--xh-glyph-stroke-light / regular / bold</code> = 1.5 / 2 / 2.5px；行内图标以 <code>--xh-glyph-baseline-shift</code>（-0.125em）压回文字基线。</li><li>图标颜色一律 <code>currentColor</code>：随语气、悬停、禁用与前景一起变，不单独上色。</li></ul><h2 id="兜底字形" tabindex="-1">兜底字形 <a class="header-anchor" href="#兜底字形" aria-label="Permalink to &quot;兜底字形&quot;">​</a></h2><p>作者没向部件放内容时，皮肤画一个默认字形：勾、叉、加减号、展开箭头、排序方向、必填星号。它们不是字符，是图标包里对应 SVG 的 <code>data:</code> URI，皮肤拿它当 <code>mask-image</code>、以 <code>currentColor</code> 着色——与用 <code>&lt;XhIcon&gt;</code> 放进去的结果一致。</p><table tabindex="0"><thead><tr><th>令牌</th><th>用途</th></tr></thead><tbody><tr><td><code>--xh-glyph-mark-check</code></td><td>各列表族的条目勾、多选框、树、穿梭框、表格勾选把手、步骤条已完成</td></tr><tr><td><code>--xh-glyph-mark-minus</code> · <code>-plus</code></td><td>半选横杠；数字框的减号、加号；悬浮按钮</td></tr><tr><td><code>--xh-glyph-mark-close</code></td><td>清空钮、关闭钮、标签与文件条目的删除钮</td></tr><tr><td><code>--xh-glyph-mark-chevron-*</code> · <code>-chevrons-*</code></td><td>展开箭头、树与侧栏的分支把手、翻页、回到顶部</td></tr><tr><td><code>--xh-glyph-mark-arrow-up</code> · <code>-arrow-down</code> · <code>-sort*</code></td><td>排序方向</td></tr><tr><td><code>--xh-glyph-mark-info</code> · <code>-warning</code></td><td>命令式 dialog / notification 的类型徽记，toast 的状态字形</td></tr><tr><td><code>--xh-glyph-mark-edit</code> · <code>-download</code> · <code>-star</code> · <code>-eye</code> · <code>-eye-off</code> · <code>-calendar</code> · <code>-clock</code> · <code>-ellipsis</code> · <code>-play</code> · <code>-pause</code></td><td>就地编辑、下载、评分、密码明暗、日期与时间触发器、更多、轮播播放</td></tr><tr><td><code>--xh-glyph-mark-zoom-*</code> · <code>-rotate-*</code> · <code>-flip-*</code> · <code>-maximize</code> · <code>-restore</code></td><td>图片查看器与浮动面板的工具条</td></tr><tr><td><code>--xh-glyph-mark-required</code></td><td>必填星号（这是文字 <code>*</code>，不是图标）</td></tr></tbody></table><p>换整套兜底字形只需覆盖这些令牌；单个部件放了作者内容时兜底字形自动让位。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ul><li>图标与文字同框时，图标贴文字 <code>--xh-space-1</code>（控件内）或 <code>--xh-space-2</code>（条目内），由家族配方给出，不手写。</li><li>只有图标的按钮必须有可访问名称（<code>aria-label</code>），走 Action Control 的 <code>icon</code> 档：正方视觉盒与控件同高。</li><li>状态不能只靠图标或颜色：错误、成功与警告同时给文案或结构通道。</li><li>装饰性图标 <code>aria-hidden</code>；承担语义的图标给 <code>role=&quot;img&quot;</code> 与名称。首方集与转换器都保留这两条路径。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/typography">字体</a> · <a href="/design/patterns">组件家族与模式</a></li><li>指南：<a href="/guide/icons">图标集</a> · 组件：<a href="/components/icon">Icon</a> · <a href="/components/icon-wrapper">IconWrapper</a></li></ul>',9))])}const y=t(r,[["render",h]]);export{u as __pageData,y as default};
